// Read-only entry verification in real product HTML and unchanged session providers.
// Synthetic JWT injection sets the authenticated precondition; it does NOT test password/MFA login.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE);
const origin=process.env.TRANSFER_QA_ORIGIN||'http://127.0.0.1:18915';
if(new URL(origin).hostname!=='127.0.0.1')throw Error('Only local synthetic fixture is allowed.');
const output=path.resolve(process.env.TRANSFER_QA_OUTPUT||'/tmp/transfer-referral-integrated');fs.mkdirSync(output,{recursive:true});
(async()=>{
 const setup=(await(await fetch(origin+'/qa/setup')).json()).web,checks=[],missing=[],exceptions=[];
 const browser=await chromium.launch({channel:'chrome',headless:true});let context,page;
 async function account(role){if(context)await context.close();context=await browser.newContext({viewport:{width:1400,height:1000},locale:'cs-CZ'});await context.route('**/*',r=>new URL(r.request().url()).origin===origin?r.continue():r.abort());await context.addInitScript(({jwt,role})=>{sessionStorage.setItem(role==='admin'?'adminAccessToken':'customerWebAccessToken',jwt);sessionStorage.setItem(role==='admin'?'adminRole':'customerWebRole',role==='admin'?'admin':'user');},{jwt:setup.users[role].jwt,role});page=await context.newPage();page.on('pageerror',e=>exceptions.push({role,message:e.message}));page.on('response',r=>{if(r.status()>=400)missing.push({role,status:r.status(),path:new URL(r.url()).pathname});});await page.goto(origin+(role==='admin'?'/web_admin/index.html':'/web/customer.html'));}
 async function close(){await page.locator('dialog.referral-dialog').getByRole('button',{name:'Zavřít',exact:true}).click();}
 try{
  await account('buyer');await page.locator('#vehiclesTab [data-vehicle-transfers-entry]').waitFor();await page.locator('#vehiclesTab [data-vehicle-transfers-entry]').click();await page.getByRole('heading',{name:'K převzetí / přijaté pozvánky'}).waitFor();assert.equal(await page.locator('[data-transfer-id]').count(),3);assert.match(await page.locator('dialog.referral-dialog').innerText(),/Převzato novým majitelem/);await close();checks.push('Real customer HTML: vehicle-list transfer entry opens real API inbox and persisted accepted invitations');
  await page.locator('[data-testid="vehicle-card"][data-vehicle-id="'+setup.vehicles.active+'"]').click();await page.getByRole('button',{name:'Správa vozidla',exact:true}).click();await page.getByRole('button',{name:'Prodat vozidlo',exact:true}).waitFor();await page.getByRole('button',{name:'Prodat vozidlo',exact:true}).click();await page.getByLabel('E-mail nového majitele · povinné').waitFor();assert.equal(await page.getByRole('button',{name:'Pokračovat k potvrzení prodeje',exact:true}).isEnabled(),true);await page.screenshot({path:path.join(output,'customer-management.png'),fullPage:true});await close();checks.push('Real vehicle detail: Správa vozidla opens capability-checked seller form with required buyer email');
  await account('seller');await page.getByTestId('tab-profile').click();await page.getByRole('button',{name:'Pozvat a získat odměny',exact:true}).click();const detail=page.locator('details[data-referral-id]').first();await detail.waitFor();await detail.locator('summary').click();assert.match(await page.locator('dialog.referral-dialog').innerText(),/web-buyer@example.com/);assert.match(await detail.innerText(),/Ověření e-mailu: Dokončeno/);await page.screenshot({path:path.join(output,'customer-referral-detail.png'),fullPage:true});await close();checks.push('Real customer Settings entry opens own verified invitee contact and status detail');
  await page.getByRole('button',{name:'Archiv vlastnictví',exact:true}).first().click();await page.locator('#customerArchivesTab').getByRole('button',{name:'Otevřít archiv',exact:true}).first().click();await page.locator('#customerFeatureDialog').waitFor();assert.equal(await page.getByRole('button',{name:'Pozvat nového majitele',exact:true}).count(),0);await page.locator('#customerFeatureDialog').getByRole('button',{name:'Zavřít',exact:true}).click();checks.push('Real archive entry: accepted/reassigned archive does not offer another owner invitation');
  await account('admin');await page.locator('#dashboard-screen:not(.hidden)').waitFor();await page.locator('button.nav-item[data-section="vehicles"]').click();await page.locator(`[data-vehicle-id="${setup.vehicles.admin}"] [data-management-action="vehicle-detail"]`).click();await page.getByRole('button',{name:'Ověřit převod vozidla',exact:true}).click();await page.getByLabel('Jak jste vlastnictví ověřili · povinné').waitFor();assert.match(await page.locator('dialog.referral-dialog').innerText(),/web-buyer@example.com/);await page.screenshot({path:path.join(output,'admin-transfer-review.png'),fullPage:true});await close();checks.push('Real administrator vehicle card/detail entry opens review token API, owner, reason and acknowledgment');
  assert.deepEqual(exceptions,[]);const result={status:'PASS',date:new Date().toISOString(),origin,checks,missingFixtureEndpoints:[...new Map(missing.map(v=>[v.role+v.path,v])).values()],limits:['Synthetic authentication precondition; password and MFA login not exercised','Fixture includes actual target routers only; listed unrelated endpoints are not mounted','No mutation in this integrated entry test; full mutations are tested separately in transfer-referral-live-20261105.cjs']};fs.writeFileSync(path.join(output,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));
 }catch(error){await page?.screenshot({path:path.join(output,'failure.png'),fullPage:true});fs.writeFileSync(path.join(output,'failure.txt'),error.stack+'\n'+await page?.locator('body').innerText());throw error;}finally{await context?.close();await browser.close();}
})().catch(error=>{console.error(error);process.exitCode=1;});
